function buildAndRunes(d){const choice=currentBuildChoice(d),current=choice?.key||'popular',selected=choice?.row,coreIds=selected?.ids||[],finals=finalItemCandidates(d,coreIds),slots=selected?sixBuildSlots(selected,finals,current,d):[],situational=rankedSituationalItemRows(d,slots.map(x=>x.id),12,{championId:$('my-champ').value,enemyId:$('enemy-champ').value,role:roleApi()});return `<div class="build-switch-wrap"><div class="${buildStatsClass(selected)}">${selected?._curated?`${text('Build curada · fuente','Curated build · source')} · <a href="${escapeHtml(selected._preset?.source||'')}" target="_blank" rel="noreferrer">${text('Abrir guía ↗','Open guide ↗')}</a>`:selected?._suggested?text('Composición propuesta a partir de objetos individuales publicados por OP.GG.','Proposal assembled from individual items published by OP.GG.'):selected?escapeHtml(rowStats(selected)):text('Sin build publicada; se muestran opciones de objetos compatibles.','No published build; compatible item options are shown.')}</div></div><div class="meta-columns build-rune-layout"><div class="build-primary-panels"><div class="build-start-boots"><section class="meta-card build-start-panel"><h3>${text('INICIO','START')}</h3>${rankedItemEntries(d.starter_items?.[0]).length?`<div class="build-icons">${rankedItemEntries(d.starter_items[0]).map(({id,index})=>buildItemIcon(id,d.starter_items[0].ids_names?.[index],'start',d.starter_items[0])).join('')}</div>`:`<p class="subtle">${text('Sin objetos publicados para Grieta del Invocador.','No Summoner’s Rift items were published.')}</p>`}</section><section class="meta-card build-boots-panel"><h3>${text('BOTAS','BOOTS')}</h3>${rankedItemEntries(d.boots?.[0]).slice(0,1).length?`<div class="build-icons">${rankedItemEntries(d.boots[0]).slice(0,1).map(({id,index})=>buildItemIcon(id,d.boots[0].ids_names?.[index],'boots',d.boots[0])).join('')}</div>`:`<p class="subtle">${text('Sin botas publicadas para Grieta del Invocador.','No Summoner’s Rift boots were published.')}</p>`}</section></div><section class="meta-card build-column"><h3>${escapeHtml(slots.length===6?text('BUILD COMPLETA · 6 OBJETOS','FULL BUILD · 6 ITEMS'):text(`NÚCLEO PUBLICADO · ${slots.length}/6 OBJETOS`,`PUBLISHED CORE · ${slots.length}/6 ITEMS`))} · ${escapeHtml(choice?.label||text('BUILD','BUILD'))}</h3>${buildTabs(d)}${buildSlotsMarkup(slots)}</section></div><section class="meta-card rune-column"><h3>${text('RUNAS','RUNES')}</h3>${runeSummary(topRunes(d))}</section>${matchupItemPanel()}<section class="meta-card build-situational-panel"><h3>${text('OTROS OBJETOS SITUACIONALES','OTHER SITUATIONAL ITEMS')}</h3>${renderSituationalGroups(situational,'situational-grid') }</section><section class="meta-card build-summoner-panel"><h3>${text('HECHIZOS DE INVOCADOR','SUMMONER SPELLS')}</h3>${summonerSpellPairs(d.summoner_spells)}</section></div>`}
function overviewBuildRunesSkills(d,skill,best){const pages=runePages(d,3),runeIndex=Math.min(overviewRuneChoice,Math.max(0,pages.length-1)),page=pages[runeIndex],runePrimary=page?(chosenRuneBuild(page).primary_page_id||page.primary_page_id):null,runeBuild=page&&d.core_items?.find(x=>(x.rune_page_id!=null&&(x.rune_page_id===page.id||x.rune_page_id===page.rune_page_id))||(runePrimary!=null&&x.primary_page_id===runePrimary)),choice=currentBuildChoice(d),current=choice?.key||'popular',selected=choice?.row,build=selected,ids=build?.ids||[],finals=finalItemCandidates(d,ids),slots=build?sixBuildSlots(build,finals,current,d):[],situational=rankedSituationalItemRows(d,slots.map(x=>x.id),12,{championId:$('my-champ').value,enemyId:$('enemy-champ').value,role:roleApi()}),skillBuild=best;return `<div class="overview-build-runes"><div class="overview-build-items-column"><section class="meta-card overview-build-heading"><div class="overview-panel-heading"><h3>${text('BUILD PRINCIPAL · CAMPEÓN Y LÍNEA','CORE BUILD · CHAMPION AND LANE')}</h3><small>${escapeHtml(choice?.label||'')}</small></div><p class="matchup-build-scope">${text('Build general de campeón/línea; los objetos situacionales se ajustan con el enemigo elegido. No hay una comparación de seis objetos medida específicamente contra este rival.','General champion/lane build; situational items adapt to your selected enemy. This six-item combination has no opponent-specific measurement.')}</p></section><div class="overview-start-boots"><section class="meta-card overview-purchase-card"><h4>${text('INICIO','START')}</h4><div class="build-icons">${(d.starter_items?.[0]?.ids||[]).map((id,i)=>buildItemIcon(id,d.starter_items[0].ids_names?.[i],'start',d.starter_items[0])).join('')||`<span class="subtle">—</span>`}</div></section><section class="meta-card overview-purchase-card overview-boot-card"><h4>${text('BOTAS','BOOTS')}</h4><div class="build-icons">${(d.boots?.[0]?.ids||[]).slice(0,1).map((id,i)=>buildItemIcon(id,d.boots[0].ids_names?.[i],'boots',d.boots[0])).join('')||`<span class="subtle">—</span>`}</div></section></div><section class="meta-card overview-summoners"><h4>${text('HECHIZOS DE INVOCADOR','SUMMONER SPELLS')}</h4>${summonerSpellPairs(d.summoner_spells?.slice(0,1))}</section><section class="overview-engine-placement"><div id="ranked-build-engine-slot"></div></section>${matchupItemPanel()}<section class="meta-card overview-situational-panel"><h4>${text('OTROS OBJETOS SITUACIONALES','OTHER SITUATIONAL ITEMS')}</h4>${renderSituationalGroups(situational,'overview-situational') }</section></div><section class="meta-card overview-rune-skill-card"><div class="overview-rune-tabs">${pages.map((r,i)=>`<button class="build-choice ${i===runeIndex?'active':''}" data-overview-rune="${i}">${text('Runas','Runes')} ${i+1} <small>${metric(r.pick_rate)}</small></button>`).join('')||`<span class="subtle">${text('Sin runas publicadas.','No runes published.')}</span>`}</div>${page?runeSummary(page):''}${skillBuild?`<div class="overview-skill"><div class="skill-order-heading"><h3>${escapeHtml((skill?.ids_names||skill?.ids||[]).join(' > '))} · ${text('SUBIDA DE HABILIDADES','SKILL LEVEL ORDER')}</h3></div>${skillLevelGrid(skillBuild.order,skill?.ids_names||skill?.ids||[],$('my-champ').value)}</div>`:''}</section></div>`}
function renderOverview(d,s){const op=matchRow(d,champions.find(c=>c.id===$('enemy-champ').value)?.key),skill=d.skill_masteries?.[0],best=[...(skill?.builds||[])].sort((a,b)=>(b.play||0)-(a.play||0))[0],style=({aggressive:text('Agresivo','Aggressive'),even:text('Equilibrado','Even'),weak:text('Débil','Weak')})[d.recommended_play_style]||d.recommended_play_style||'—',advice=matchupAdvice(d);return `<div class="stat-grid">${statCard(text('WIN RATE','WIN RATE'),metric(s.win_rate),`${text('en','in')} ${roleName()}`)}${statCard(text('POPULARIDAD','PICK RATE'),metric(s.pick_rate),`${Number(s.play||0).toLocaleString(lang==='es'?'es-ES':'en-US')} ${text('partidas','games')}`)}${statCard(text('BAN RATE','BAN RATE'),metric(s.ban_rate))}${statCard('KDA',Number(s.kda||0).toFixed(2))}${statCard(`${text('VS','VS')} ${champName($('enemy-champ').value).toUpperCase()}`,op?metric(winRate(op)):text('Sin muestra','No sample'),op?`${op.play.toLocaleString(lang==='es'?'es-ES':'en-US')} ${text('partidas','games')}`:text('sin datos publicados','no published data'))}</div>${overviewBuildRunesSkills(d,skill,best)}<div class="meta-card overview-fight-card"><h3>${text('Cómo abordar la pelea vs','How to approach the fight vs')} ${escapeHtml(champName($('enemy-champ').value))}</h3><div class="fight-tip-grid">${advice.slice(0,4).map((tip,i)=>`<article class="fight-tip"><b class="fight-tip-head">${tip.ability?.icon?`<img src="${escapeHtml(tip.ability.icon)}" alt=""> <i>${escapeHtml(tip.ability.key)}</i> `:''}${i+1}. ${escapeHtml(tip.title)}${tip.ability?.name?` · ${escapeHtml(tip.ability.name)}`:''}</b><p>${escapeHtml(tip.body)}</p><small>${escapeHtml(tip.source)}</small></article>`).join('')||`<p>${text('No hay consejos publicados para este campeón.','No published advice for this champion.')}</p>`}</div>${d.recommended_play_style?`<p class="why-note">${text('Estilo sugerido por OP.GG:','OP.GG suggested play style:')} ${escapeHtml(style)}.</p>`:''}</div>`}
function renderFullBuild(d){return buildAndRunes(d)}
function buildCard(title,row,d){if(!row)return `<section class="meta-card"><h3>${escapeHtml(title)}</h3><p class="subtle">No hay muestra suficiente.</p></section>`;const rune=topRunes(d),skill=d.skill_masteries?.[0];return `<section class="meta-card"><h3>${escapeHtml(title)}</h3><p class="subtle">${rowStats(row)}</p><div class="item-row">${(row.ids||[]).map((id,i)=>itemTile(id,row.ids_names?.[i],true)).join('')}</div><div class="meta-columns compact">${itemBuildCard('Inicio',d.starter_items?.[0])||''}${itemBuildCard('Botas',d.boots?.[0])||''}</div><h4>Runas frecuentes</h4>${runeSummary(rune)}<h4>Prioridad de habilidades</h4>${skillSummary(skill)}</section>`}
function matchupAdvice(d){const myId=$('my-champ').value,enemyId=$('enemy-champ').value,own=cachedChampionDetail(myId),enemy=cachedChampionDetail(enemyId),tips=[],add=(title,body,source)=>{const key=String(body||'').trim().toLowerCase();if(body&& !tips.some(x=>x.body.toLowerCase()===key))tips.push({title,body,source})};for(const tip of enemy?.enemytips||[])add(text(`Contra ${champName(enemyId)}`,'Against '+champName(enemyId)),tip,text('Data Dragon · consejo contra el campeón','Data Dragon · counter tip'));for(const tip of own?.allytips||[])add(text(`Juega ${champName(myId)} así`,'Playing '+champName(myId)),tip,text('Data Dragon · consejo del campeón','Data Dragon · champion tip'));if(lang==='en'&&d.opponent_champion_tip)add(text('Consejo del matchup','Matchup tip'),d.opponent_champion_tip,'OP.GG MCP');const cc=/stun|root|knock|suppress|immobil|aturd|ralentiz|derrib|inmoviliz|suprim/i,threat=enemy?.spells?.find(s=>cc.test(`${s.name} ${s.description} ${s.tooltip}`))||enemy?.spells?.[3]||enemy?.spells?.[0],threatName=threat?.name||text('habilidad clave','key ability');const generated=lang==='es'?[[`${text('Contra '+champName(enemyId)+' · Ventana de entrada','Against '+champName(enemyId)+' · Entry window')}`,`Espera a que ${champName(enemyId)} use o falle ${threatName} antes de comprometerte con el intercambio.`],[`${text('Contra '+champName(enemyId)+' · Conserva una salida','Against '+champName(enemyId)+' · Keep an escape')}`,`No gastes tu movilidad para iniciar si ${threatName} sigue disponible; guarda una herramienta para salir o esquivarla.`],[`${text('Contra '+champName(enemyId)+' · Plan de pelea','Against '+champName(enemyId)+' · Fight plan')}`,`Cuando ${threatName} esté en enfriamiento, busca un intercambio corto y vuelve a medir antes de alargarlo.`],[`${text('Contra '+champName(enemyId)+' · Pelea en equipo','Against '+champName(enemyId)+' · Teamfight')}`,`Evita entrar primero mientras ${threatName} pueda detenerte; coordina el inicio con tu equipo.`],[`${text('Contra '+champName(enemyId)+' · Oleada y visión','Against '+champName(enemyId)+' · Wave and vision')}`,`Busca el intercambio con la oleada en una posición segura y coloca visión antes de avanzar para reducir el riesgo de una emboscada.`]]:[['Entry window',`Wait for ${champName(enemyId)} to use or miss ${threatName} before committing to the trade.`],['Keep an escape',`Do not spend your mobility to start if ${threatName} is available; save a tool to disengage or dodge it.`],['Fight plan',`When ${threatName} is on cooldown, look for a short trade and reassess before extending it.`],['Teamfight',`Avoid going in first while ${threatName} can stop you; coordinate the engage with your team.`],['Wave and vision',`Look for trades with the wave in a safe position and place vision before moving forward to reduce ambush risk.`]];for(const [title,body] of generated){if(tips.length>=5)break;add(title,body,text('Plan táctico sugerido a partir del kit','Tactical suggestion based on the champion kit'))}const spellToken=(spell,index)=>({key:['Q','W','E','R'][index]||'R',name:spell.name,icon:`${API}/cdn/${patch}/img/spell/${spell.image?.full||''}`});return tips.slice(0,8).map(tip=>{const candidates=[...(enemy?.spells||[]).map((spell,index)=>({spell,index})),...(own?.spells||[]).map((spell,index)=>({spell,index}))],match=candidates.find(x=>x.spell.name&&`${tip.title} ${tip.body}`.toLowerCase().includes(x.spell.name.toLowerCase()));return {...tip,ability:match?spellToken(match.spell,match.index):threat?spellToken(threat,Math.max(0,enemy?.spells?.indexOf(threat))):null}})}
function renderMatchups(d){const id=champions.find(c=>c.id===$('enemy-champ').value)?.key,selected=matchRow(d,id),rows=[...(d.counters||[])].filter(x=>x.play>0).sort((a,b)=>Number(b.play||0)-Number(a.play||0)),champLabel=x=>championsByLocale[lang]?.find(c=>Number(c.key)===Number(x.champion_id))?.name||x.champion_name,advice=matchupAdvice(d);return `<section class="meta-card"><h3>${text('Este enfrentamiento','This matchup')} · ${escapeHtml(champName($('enemy-champ').value))}</h3><p>${selected?text('OP.GG incluye este enfrentamiento en sus datos agregados.','OP.GG includes this matchup in its aggregate data.'):text('OP.GG no publicó un registro directo para este rival.','OP.GG did not publish a direct entry for this opponent.')}</p></section><section class="meta-card fight-advice"><h3>${text('Cómo abordar la pelea vs','How to approach a fight vs')} ${escapeHtml(champName($('enemy-champ').value))}</h3><div class="fight-tip-grid">${advice.map((x,i)=>`<article class="fight-tip"><b class="fight-tip-head">${x.ability?.icon?`<img src="${escapeHtml(x.ability.icon)}" alt=""> <i>${escapeHtml(x.ability.key)}</i> `:''}${i+1}. ${escapeHtml(x.title)}${x.ability?.name?` · ${escapeHtml(x.ability.name)}`:''}</b><p>${escapeHtml(x.body)}</p><small>${escapeHtml(x.source)}</small></article>`).join('')}</div></section><section class="meta-card"><h3>${text('Otros enfrentamientos incluidos en la fuente','Other matchups in the source')}</h3>${matchupList(rows.slice(0,14),champLabel)}</section>`}
function matchupList(rows,label){return rows.length?`<div class="matchup-list">${rows.map(x=>`<div><span>${escapeHtml(label(x))}</span></div>`).join('')}</div>`:'Sin datos publicados.'}
function runeTree(id){return (runesByLocale[lang]||[]).find(x=>Number(x.id)===Number(id))}
function runeById(id){for(const tree of runesByLocale[lang]||[])for(const slot of tree.slots||[])for(const rune of slot.runes||[])if(Number(rune.id)===Number(id))return rune;return null}
function runeIcon(rune,selected){if(!rune)return '';const desc=(rune.longDesc||rune.shortDesc||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(),colored=escapeHtml(desc).replace(/([+−-]?\d[\d.,]*(?:%|\s*(?:s|sec|seconds?|seg|segundos?)\b)?)/gi,'<i class="rune-value">$1</i>').replace(/(damage|healing|shield|speed|daño|curación|escudo|velocidad|slow|ralentiza|cooldown|enfriamiento)/gi,'<b class="rune-action">$1</b>');return `<span class="rune-icon-wrap ${selected?'selected':''}" tabindex="0" aria-label="${escapeHtml(`${rune.name}. ${desc}`)}"><img src="${API}/cdn/img/${rune.icon}" alt="${escapeHtml(rune.name)}"><span class="rune-tooltip"><b>${escapeHtml(rune.name)}</b><small>${colored}</small></span></span>`}
function statShardMeta(id){return ({5001:{icon:'♥',type:'health'},5002:{icon:'♥',type:'health'},5003:{icon:'⬟',type:'armor'},5004:{icon:'⬡',type:'resist'},5005:{icon:'➤',type:'speed'},5007:{icon:'◷',type:'haste'},5008:{icon:'⚔',type:'adaptive'},5009:{icon:'⚔',type:'adaptive'}})[Number(id)]||{icon:'✦',type:'adaptive'}}
function statShardName(id,index){const slot=lang==='es'?['Ofensiva','Flexible','Defensiva'][index]:['Offense','Flex','Defense'][index];const known=({5001:text('Vida por nivel','Scaling health'),5002:text('Vida','Health'),5003:text('Armadura','Armor'),5004:text('Resistencia mágica','Magic resist'),5005:text('Velocidad de ataque','Attack speed'),5007:text('Aceleración de habilidad','Ability haste'),5008:text('Fuerza adaptable','Adaptive force'),5009:text('Fuerza adaptable','Adaptive force')})[Number(id)];return `${slot} · ${known||`${text('fragmento','shard')} ${id}`}`}
function renderRuneTree(tree,ids,kind){if(!tree)return `<div class="rune-tree-empty">${text('Árbol no disponible','Rune tree unavailable')}</div>`;const selected=new Set((ids||[]).map(Number));return `<section class="rune-tree ${kind}"><header><img src="${API}/cdn/img/${tree.icon}" alt=""><b>${escapeHtml(tree.name)}</b></header><div class="rune-tree-rows">${tree.slots.map((slot,i)=>`<div class="rune-row-icons ${i===0?'keystones':''}">${slot.runes.map(r=>runeIcon(r,selected.has(Number(r.id)))).join('')}</div>`).join('')}</div></section>`}
function chosenRuneBuild(r){return [...(r?.builds||[])].sort((a,b)=>(b.play||0)-(a.play||0))[0]||r}
function runeSummary(r){if(!r)return `<p class="subtle">${text('Sin datos de runas.','No rune data available.')}</p>`;const b=chosenRuneBuild(r),primary=runeTree(b.primary_page_id||r.primary_page_id),secondary=runeTree(b.secondary_page_id||r.secondary_page_id),primaryIds=b.primary_rune_ids||[],secondaryIds=b.secondary_rune_ids||[],statIds=b.stat_mod_ids||[];return `<div class="rune-full-layout">${renderRuneTree(primary,primaryIds,'primary-tree')}${renderRuneTree(secondary,secondaryIds,'secondary-tree')}</div><div class="stat-shards">${statIds.map((id,i)=>{const meta=statShardMeta(id);return `<span class="shard-${meta.type}"><small>${i===0?text('Ofensiva','Offense'):i===1?text('Flexible','Flex'):text('Defensiva','Defense')}</small><b><i>${meta.icon}</i>${escapeHtml(statShardName(id,i).split(' · ')[1])}</b></span>`}).join('')}</div><p class="subtle">${text('Popularidad','Popularity')} ${metric(b.pick_rate??r.pick_rate)} · ${text('win rate','win rate')} ${metric(winRate(b.play?b:r))} · ${Number(b.play||r.play||0).toLocaleString(lang==='es'?'es-ES':'en-US')} ${text('partidas','games')}</p>`}
function renderRunes(d){const pages=runePages(d,3),selectedIndex=Math.min(overviewRuneChoice,Math.max(0,pages.length-1)),selected=pages[selectedIndex],build=selected&&chosenRuneBuild(selected),tree=build&&runeTree(build.primary_page_id||selected.primary_page_id);return pages.length?`<div class="rune-choice-tabs">${pages.map((r,i)=>{const b=chosenRuneBuild(r),primary=runeTree(b.primary_page_id||r.primary_page_id);return `<button class="build-choice ${i===selectedIndex?'active':''}" data-overview-rune="${i}">${text('Runas','Runes')} ${i+1} · ${escapeHtml(primary?.name||text('Página','Page'))} <small>${i===selectedIndex?text('Seleccionada','Selected'):text('Usar','Select')}</small></button>`}).join('')}</div><section class="meta-card selected-rune-page"><h3>${text('Página activa en tu guía','Active rune page in your guide')} · ${escapeHtml(tree?.name||'')}</h3>${runeSummary(selected)}</section><div class="disclaimer">${text('La selección cambia la guía y el overlay de Rift Companion; no modifica la página de runas del cliente de League.','This selection updates the Rift Companion guide and overlay; it does not edit the League client rune page.')}</div>`:`<div class="empty-panel">${text('No hay páginas de runas publicadas para esta selección.','No rune pages were published for this selection.')}</div>`}
