function closeActiveTooltips(except=null){document.querySelectorAll('[data-tooltip-active="true"]').forEach(node=>{if(node!==except)node.dataset.tooltipActive='false'})}
function setTooltipPlacement(node){const selector=node.matches('.build-item')?'.build-item-tooltip':node.matches('.rune-icon-wrap')?'.rune-tooltip':'.aram-augment-tooltip',tooltip=node.querySelector(selector);if(!tooltip)return;closeActiveTooltips(node);node.dataset.tooltipActive='true';tooltip.classList.add('tooltip-scroll-content');tooltip.tabIndex=0;tooltip.setAttribute('aria-label',tooltip.getAttribute('aria-label')||text('Detalles desplazables','Scrollable details'));node.classList.remove('tooltip-below','tooltip-align-left','tooltip-align-right');tooltip.style.position='fixed';tooltip.style.transform='none';tooltip.style.left='0px';tooltip.style.right='auto';tooltip.style.top='0px';tooltip.style.bottom='auto';const tip=tooltip.getBoundingClientRect(),anchor=node.getBoundingClientRect(),margin=8,item=node.matches('.build-item'),roomRight=window.innerWidth-anchor.right,roomLeft=anchor.left,left=item?(roomRight>=tip.width+margin||roomRight>=roomLeft?Math.min(window.innerWidth-tip.width-margin,anchor.right+margin):Math.max(margin,anchor.left-tip.width-margin)):Math.max(margin,Math.min(anchor.left+(anchor.width-tip.width)/2,window.innerWidth-tip.width-margin)),above=anchor.top-tip.height-margin>=margin,top=item?Math.max(margin,Math.min(anchor.top-12,window.innerHeight-tip.height-margin)):above?anchor.top-tip.height-margin:Math.min(anchor.bottom+margin,window.innerHeight-tip.height-margin);tooltip.style.left=`${left}px`;tooltip.style.top=`${Math.max(margin,top)}px`}
document.addEventListener('pointerover',e=>{const node=e.target.closest('.build-item,.rune-icon-wrap,.aram-augment');if(node){if(!node.contains(e.relatedTarget)||node.dataset.tooltipActive!=='true')setTooltipPlacement(node)}else if(!e.target.closest('.tooltip-scroll-content'))closeActiveTooltips()},true);
document.addEventListener('pointerout',e=>{const node=e.target.closest('.build-item,.rune-icon-wrap,.aram-augment');if(node&&!node.contains(e.relatedTarget))node.dataset.tooltipActive='false'},true);
document.addEventListener('focusin',e=>{const node=e.target.closest('.build-item,.rune-icon-wrap,.aram-augment');if(node)setTooltipPlacement(node)},true);
document.addEventListener('focusout',e=>{const node=e.target.closest('.build-item,.rune-icon-wrap,.aram-augment');if(node&&!node.contains(e.relatedTarget))node.dataset.tooltipActive='false'},true);

(()=>{
  const escHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const t=(es,en)=>text(es,en),championOptions=()=>'<option value="">—</option>'+champions.map(c=>'<option value="'+escHtml(c.id)+'">'+escHtml(c.name)+'</option>').join('');  function openManualRoster(){
    const options=championOptions();let dialog=document.getElementById('manual-roster-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='manual-roster-dialog';document.body.append(dialog)}
    dialog.innerHTML='<form method="dialog" class="manual-roster-dialog"><header><h2>'+t('Preparar equipos manualmente','Prepare teams manually')+'</h2><button value="cancel">×</button></header><p>'+t('Selecciona los campeones conocidos, indica los equipos y marca quién eres. Los datos no confirmados no se usarán como picks reales.','Select known champions, assign teams, and mark yourself. Unconfirmed entries are not treated as real picks.')+'</p><div class="manual-roster-controls"><button type="button" id="manual-roster-invert">'+t('Invertir equipos','Swap teams')+'</button></div><div id="manual-roster-rows"></div><div class="manual-roster-controls"><label>'+t('Este soy yo','This is me')+'<select id="manual-roster-mine"></select></label><label>'+t('Rival de línea (opcional)','Lane opponent (optional)')+'<select id="manual-roster-opponent"></select></label></div><p id="manual-roster-coverage"></p><p id="manual-roster-status" role="status"></p><footer><button type="button" id="manual-roster-save">'+t('Guardar preparación','Save preparation')+'</button></footer></form>';
    const q=id=>dialog.querySelector('#'+id),host=q('manual-roster-rows'),roles=[['','—'],['top','Top'],['jungle',t('Jungla','Jungle')],['mid','Mid'],['adc','ADC'],['support',t('Soporte','Support')]];
    host.innerHTML=Array.from({length:10},(_,i)=>'<div class="manual-roster-row"><select class="manual-roster-champ" aria-label="Champion '+(i+1)+'">'+options+'</select><select class="manual-roster-team" aria-label="Team '+(i+1)+'"><option value="none">'+t('Sin asignar','Unassigned')+'</option><option value="ally">'+t('Aliado','Ally')+'</option><option value="enemy">'+t('Enemigo','Enemy')+'</option></select><select class="manual-roster-role" aria-label="Role '+(i+1)+'">'+roles.map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('')+'</select></div>').join('');
    const read=()=>[...host.children].map(row=>({champion:row.querySelector('.manual-roster-champ').value,team:row.querySelector('.manual-roster-team').value,role:row.querySelector('.manual-roster-role').value}));
    function refresh(){for(const [id,team]of [['manual-roster-mine','ally'],['manual-roster-opponent','enemy']]){const select=q(id),old=select.value;select.innerHTML='<option value="">—</option>'+read().filter(r=>r.champion&&r.team===team).map(r=>'<option value="'+escHtml(r.champion)+'">'+escHtml(champName(r.champion))+'</option>').join('');select.value=old}const filled=read().filter(r=>r.champion).length;q('manual-roster-coverage').textContent=filled+'/10 · '+t(filled===10?'Revisa roles y equipos':'Composición incompleta',filled===10?'Review roles and teams':'Incomplete composition')}
    host.onchange=refresh;q('manual-roster-invert').onclick=()=>{const swapped=RiftPhaseA.invertTeams(read());[...host.children].forEach((row,i)=>row.querySelector('.manual-roster-team').value=swapped[i].team);refresh()};
    q('manual-roster-save').onclick=()=>{const result=RiftPhaseA.validateRoster({rows:read(),mine:q('manual-roster-mine').value,opponent:q('manual-roster-opponent').value},champions.map(c=>c.id));if(!result.valid){const messages={champion:t('Campeón desconocido','Unknown champion'),team:t('Asigna el equipo','Assign a team'),role:t('Rol inválido','Invalid role'),duplicate:t('Campeón repetido','Duplicate champion'),size:t('Máximo cinco por lado','Maximum five per side'),mine:t('Elige tu campeón aliado','Choose your allied champion'),opponent:t('El rival debe ser enemigo','Opponent must be enemy')};q('manual-roster-status').textContent=result.errors.map(e=>messages[e]||e).join(' · ');return}
      const mine=q('manual-roster-mine').value,opponent=q('manual-roster-opponent').value,state={schemaVersion:1,confirmed:true,status:result.complete?'complete':'partial',coverage:result.coverage,myChampion:mine,laneOpponentId:opponent||null,ally:result.ally,enemy:result.enemy,at:new Date().toISOString()};if(activeLcuRoster){lcuOverrides.championId=mine;lcuOverrides.role=result.myPlayer.role||$('role').value;lcuOverrides.laneOpponentId=opponent||'';manualRosterOverride={draftSessionId:activeLcuRoster.draftSessionId,ally:result.ally,enemy:result.enemy}}const old=localStorage.getItem('rift-last-detected-rosters');if(old)localStorage.setItem('rift-last-detected-rosters-backup',old);localStorage.setItem('rift-last-detected-rosters',JSON.stringify(state));$('my-champ').value=mine;if(result.myPlayer.role)$('role').value=result.myPlayer.role;setSearchValue('my-champ-search','my-champ');updatePortrait(mine,'my-img');if(opponent){$('enemy-champ').value=opponent;manualLaneSelectionId=opponent;setSearchValue('enemy-champ-search','enemy-champ');updatePortrait(opponent,'enemy-img')}else{manualLaneSelectionId='';$('enemy-champ').value='';$('enemy-champ-search').value='';updatePortrait('','enemy-img')}dialog.close();switchPage('draft');showDraft();if(activeLcuRoster)renderEngineRecommendations();if(!result.complete)notify(t('Guía provisional guardada; puedes completar los equipos cuando conozcas más campeones.','Provisional guide saved; complete the teams as you learn more champions.'))};
    try{const saved=JSON.parse(localStorage.getItem('rift-last-detected-rosters')||'null');if(saved){const restored=[...(saved.ally||[]).map(r=>({...r,team:'ally'})),...(saved.enemy||[]).map(r=>({...r,team:'enemy'}))].slice(0,10);[...host.children].forEach((row,i)=>{const entry=restored[i];if(!entry)return;row.querySelector('.manual-roster-champ').value=entry.champion;row.querySelector('.manual-roster-team').value=entry.team;row.querySelector('.manual-roster-role').value=entry.role||''});refresh();q('manual-roster-mine').value=saved.myChampion||'';q('manual-roster-opponent').value=saved.laneOpponentId||''}}catch{q('manual-roster-status').textContent=t('La preparación guardada no se pudo leer.','The saved preparation could not be read.')}
    refresh();if(!dialog.open)dialog.showModal();
  }
  const manualButton=document.createElement('button');manualButton.type='button';manualButton.dataset.manualPreparation='true';manualButton.className='btn-outline';manualButton.textContent=text('Preparar equipos','Prepare teams');manualButton.onclick=openManualRoster;document.getElementById('create-ranked-build')?.parentElement?.append(manualButton);
})();
