function selectRankedScenario(scenario,variantId=''){
  const row=engineRecommendation?.scenarios?.[scenario];if(!row)return;
  engineScenarioSelection=scenario;engineRecommendation.options=row.variants||[];
  engineBuildSelectionId=engineRecommendation.options.some(option=>option.id===variantId)?variantId:row.recommended?.id||'';buildSelection='engine-'+engineBuildSelectionId;
  const chosen=engineRecommendation.options.find(option=>option.id===engineBuildSelectionId);if(!chosen?.items?.some(item=>String(item.id)===String(engineSelectedItemId)))engineSelectedItemId=String(chosen?.items?.[0]?.id||'');
  if(activeTab==='overview'&&(metaData?.data?.summary||metaData?.data?.data?.summary)){renderMeta({skipEngine:true});if(!$('engine-build-card'))engineBuildInsertion($('meta-panel')).host?.insertAdjacentHTML(engineBuildInsertion($('meta-panel')).position,'<section class="meta-card engine-build-card" id="engine-build-card"></section>')}if($('engine-build-card'))renderRankedScenarioCard($('engine-build-card'));sendOverlay();
}
function selectRankedItem(itemId){
  const selected=(engineRecommendation?.scenarios?.[engineScenarioSelection]?.variants||[]).find(option=>option.id===engineBuildSelectionId);
  if(!selected?.items?.some(item=>String(item.id)===String(itemId)))return;
  engineSelectedItemId=String(itemId);if($('engine-build-card'))renderRankedScenarioCard($('engine-build-card'));sendOverlay();
}
const RANKED_VISIBLE_VARIANTS=3;
function rankedVariantTabs(options,selectedId){
  const visible=options.slice(0,RANKED_VISIBLE_VARIANTS),extra=options.slice(RANKED_VISIBLE_VARIANTS),button=option=>'<button type="button" title="'+escapeHtml(option.label||text('Alternativa','Alternative'))+'" aria-label="'+escapeHtml(option.label||text('Alternativa','Alternative'))+'" data-engine-variant="'+escapeHtml(option.id)+'" aria-pressed="'+(option.id===selectedId)+'">'+escapeHtml(option.label||text('Alternativa','Alternative'))+'</button>';
  return '<nav class="engine-variant-tabs">'+visible.map(button).join('')+'</nav>'+(extra.length?'<details class="engine-more-variants" '+(extra.some(option=>option.id===selectedId)?'open':'')+'><summary>'+text(`Más alternativas (${extra.length})`,`More alternatives (${extra.length})`)+'</summary><nav class="engine-variant-tabs">'+extra.map(button).join('')+'</nav></details>':'');
}
function renderRankedScenarioCard(card){
  if(!card||!engineRecommendation?.scenarios)return;
  const scenarios=engineRecommendation.scenarios,group=scenarios[engineScenarioSelection]||scenarios.standard;
  const options=group.variants||[],selected=options.find(option=>option.id===engineBuildSelectionId)||group.recommended;
  if(selected)engineBuildSelectionId=selected.id;
  if(!selected?.items?.some(item=>String(item.id)===String(engineSelectedItemId)))engineSelectedItemId=String(selected?.items?.[0]?.id||'');
  const selectedItem=selected?.items?.find(item=>String(item.id)===String(engineSelectedItemId)),selectedWhy=selectedItem?.education?.whyFits?.text||selected?.itemExplanations?.[engineSelectedItemId]?.whyFits?.text||selected?.purchaseOrder?.find(step=>String(step.finalItemId)===engineSelectedItemId)?.whyFits?.text||'';
  const routeComparison=engineScenarioSelection==='lane'&&$('my-champ')?.value==='Ahri'&&$('enemy-champ')?.value==='Zed'?(selected?.purchaseRouteComparisons||[]):[];
  card.innerHTML='<nav class="engine-scenario-tabs">'+Object.entries(scenarios).map(([id,row])=>'<button type="button" data-engine-scenario="'+escapeHtml(id)+'" aria-pressed="'+(id===engineScenarioSelection)+'">'+escapeHtml(row.label||id)+'</button>').join('')+'</nav>'+
    rankedVariantTabs(options,selected?.id)+
    (selected?'<article class="engine-selected-build" data-selected-build="'+escapeHtml(selected.id)+'"><h3>'+escapeHtml(selected.label)+'</h3><p class="engine-provenance">'+escapeHtml(selected.evidenceType==='observed-exact'?text('Combinación exacta publicada','Exact published combination'):selected.evidenceType==='educational-from-core'?text('Propuesta educativa desde núcleo publicado','Educational proposal from published core'):text('Propuesta educativa editorial','Editorial educational proposal'))+'</p><div class="engine-item-row">'+selected.items.map((item,index)=>'<button type="button" class="engine-item-slot'+(String(item.id)===engineSelectedItemId?' selected':'')+'" data-ranked-item="'+escapeHtml(item.id)+'" aria-pressed="'+(String(item.id)===engineSelectedItemId)+'" aria-label="'+escapeHtml(text(`Objeto ${index+1}: ${itemName(item.id)}`,`Item ${index+1}: ${itemName(item.id)}`))+'"><small>'+String(index+1)+'</small>'+buildItemIcon(item.id,itemName(item.id),'suggested',{education:item.education})+'</button>').join('')+'</div>'+
    (selectedItem?'<section class="engine-slot-fit" aria-live="polite"><b>'+text('POR QUÉ ENCAJA','WHY IT FITS')+' · '+String(selected.items.findIndex(item=>String(item.id)===engineSelectedItemId)+1)+'. '+escapeHtml(itemName(selectedItem.id))+'</b><p>'+escapeHtml(selectedWhy||text('La fuente no publicó un motivo individual para este objeto.','The source did not provide an item-specific reason.'))+'</p></section>':'')+
    (routeComparison.length===3?'<details class="engine-route-comparison"><summary>'+text('Comparar tres rutas · Ahri contra Zed','Compare three routes · Ahri vs Zed')+'</summary><p class="subtle">'+text('Proyección educativa. La comparación considera presión de línea y nivel observados, además de oro y componentes confirmados; si faltan, ninguna ruta se declara superior.','Educational projection. Comparison uses observed lane pressure and level plus confirmed gold and components; without them, no route is ranked superior.')+'</p><ol>'+routeComparison.map(route=>'<li><b>'+escapeHtml(route.title)+'</b><small>'+escapeHtml(route.rationale)+'</small><em>'+escapeHtml(route.preferred?text('Respaldada condicionalmente por estos datos','Conditionally supported by these observations'):text('Condicional; no se afirma que sea superior','Conditional; not claimed as superior'))+'</em></li>').join('')+'</ol></details>':'')+'</article>':'<p>'+escapeHtml(group.partial?.reason||text('Faltan candidatos revisados.','Reviewed candidates are missing.'))+'</p>');
  card.onclick=event=>{const scenario=event.target.closest('[data-engine-scenario]'),variant=event.target.closest('[data-engine-variant]'),item=event.target.closest('[data-ranked-item]');if(scenario)selectRankedScenario(scenario.dataset.engineScenario);else if(variant)selectRankedScenario(engineScenarioSelection,variant.dataset.engineVariant);else if(item)selectRankedItem(item.dataset.rankedItem);};
}
window.rift?.onOverlayBuildChoice?.(choice=>choice?.itemId?selectRankedItem(choice.itemId):selectRankedScenario(choice.scenario,choice.variantId||''));
document.addEventListener('click',event=>{const scenario=event.target.closest('[data-overview-scenario]');if(scenario)selectRankedScenario(scenario.dataset.overviewScenario)});
